 case S::RetainSecond:f.push(v[2].er);(**selected).depth+=4;break;case S::RetainFirst:f.push(v[1].er);(**selected).depth+=4;break;case S::FirstBOffset:case S::FirstAOffset:f.move(v[4].r,5);break;case S::SecondBOffset:case S::SecondAOffset:f.move(v[4].r,6);break;case S::CaptureSecond:f.move(v[1].er,v[2].er);break;case S::RestoreFirst:case S::RestoreSecond:f.pop(v[1].er);(**selected).depth-=4;break;
